#!/usr/bin/env node
//
// generate-userguide-rollup.mjs — deterministic "Delivered features
// (generated)" rollup in docs/USER_GUIDE.md, built from docs/product/*.md
// (D4, docs/specs/SPEC-0092-spec-product-docs-enforced.md).
//
// Renders ONE marker-delimited section:
//   <!-- AAI:USERGUIDE-ROLLUP:BEGIN (auto-generated, do not edit by hand) -->
//   ...
//   <!-- AAI:USERGUIDE-ROLLUP:END -->
// CONTAINMENT: every byte OUTSIDE the markers is preserved verbatim. When the
// markers are absent (first run) the block is appended at EOF; a subsequent
// run replaces strictly the span between (and including) the marker lines.
// BYTE-IDEMPOTENCE: the rendered block carries NO volatile content (no
// generation timestamp), so a second run over unchanged inputs is
// byte-identical.
//
// Per product doc (docs/product/<slug>.md, keyed on the SAME slug identity
// the close-work-item.mjs gate uses — SEAM 3): the H1 title, a link to the
// product doc + its `spec`, and the "What it does" section's first
// paragraph. Sorted by frontmatter `updated` descending (stable tie-break by
// slug for equal/absent `updated`). A product doc that fails the D2
// placeholder predicate (lib/product-doc.mjs, shared with the close-work-item
// gate) is EXCLUDED — a half-written product doc never leaks into the guide.
//
// Usage: node .aai/scripts/generate-userguide-rollup.mjs [--output <path>]
// Read-only over docs/product/**; writes only the target USER_GUIDE file.
// Node stdlib only (docs/TECHNOLOGY.md).

import fs from 'node:fs';
import path from 'node:path';
import { missingProductSections, extractSection } from './lib/product-doc.mjs';

const ROOT = process.cwd();

// Anchored to a STANDALONE line (PR #166 Codex P2): a marker-like string
// embedded mid-line in hand prose must never become the splice anchor.
const BEGIN_RE = /^<!--[ \t]*AAI:USERGUIDE-ROLLUP:BEGIN[^\n]*-->[ \t]*$/m;
const END_RE = /^<!--[ \t]*AAI:USERGUIDE-ROLLUP:END[ \t]*-->[ \t]*$/m;
const END_MARKER = '<!-- AAI:USERGUIDE-ROLLUP:END -->';
const BEGIN_MARKER = '<!-- AAI:USERGUIDE-ROLLUP:BEGIN (auto-generated by generate-userguide-rollup.mjs, do not edit by hand) -->';

function parseArgs(argv) {
  const args = { outputPath: 'docs/USER_GUIDE.md' };
  for (let i = 2; i < argv.length; i += 1) {
    const tok = argv[i];
    if (tok === '--output' && argv[i + 1]) { args.outputPath = argv[i + 1]; i += 1; continue; }
    if (tok === '-h' || tok === '--help') {
      console.log('Usage: generate-userguide-rollup.mjs [--output <USER_GUIDE.md path>]');
      process.exit(0);
    }
  }
  return args;
}

function parseFrontmatter(content) {
  const norm = String(content).replace(/\r\n?/g, '\n');
  const m = norm.match(/^---\n([\s\S]*?)\n---/);
  const out = {};
  if (!m) return out;
  for (const line of m[1].split('\n')) {
    const km = line.match(/^([a-zA-Z_][\w-]*):\s*(.*)$/);
    if (km) out[km[1]] = km[2].trim().replace(/^["']|["']$/g, '');
  }
  return out;
}

// The section's first paragraph, comments stripped, whitespace collapsed to
// single spaces (one clean summary line — never multi-paragraph bleed).
function firstParagraph(body) {
  if (!body) return '';
  const stripped = body.replace(/<!--[\s\S]*?-->/g, '').trim();
  const para = stripped.split(/\n[ \t]*\n/)[0] ?? '';
  return para.replace(/\s+/g, ' ').trim();
}

// A repo-root-relative path (e.g. "docs/specs/SPEC-1.md") relativized to the
// docs/ directory USER_GUIDE.md lives in ("specs/SPEC-1.md"); passthrough for
// anything that does not start with "docs/" (already relative, or absent).
function relFromDocsDir(p) {
  if (!p) return null;
  return p.startsWith('docs/') ? p.slice('docs/'.length) : p;
}

function loadProductDocs(root) {
  const productDir = path.join(root, 'docs/product');
  let files = [];
  try {
    files = fs.readdirSync(productDir).filter((f) => f.endsWith('.md')).sort();
  } catch {
    return [];
  }
  const docs = [];
  for (const file of files) {
    const abs = path.join(productDir, file);
    let content;
    try { content = fs.readFileSync(abs, 'utf8'); } catch { continue; }
    if (missingProductSections(content).length > 0) continue; // D2 — placeholder-rejecting
    const fm = parseFrontmatter(content);
    const h1 = content.match(/^#[ \t]+(.+)$/m);
    const slug = fm.id ?? file.replace(/\.md$/, '');
    docs.push({
      slug,
      title: h1 ? h1[1].trim() : slug,
      spec: relFromDocsDir(fm.spec ?? null),
      updated: fm.updated ?? '',
      summary: firstParagraph(extractSection(content, 'What it does')),
      docLink: `product/${file}`,
    });
  }
  // Sort by updated DESC; stable tie-break by slug (D4 edge case: no `updated`
  // field / equal values still yield a deterministic, reproducible order).
  docs.sort((a, b) => {
    if (a.updated !== b.updated) return a.updated < b.updated ? 1 : -1;
    return a.slug.localeCompare(b.slug);
  });
  return docs;
}

function esc(s) {
  return String(s ?? '');
}

function renderEntry(d) {
  const links = [`[Product doc](${esc(d.docLink)})`];
  if (d.spec) links.push(`[Spec](${esc(d.spec)})`);
  const lines = [`### ${esc(d.title)}`, ''];
  if (d.summary) { lines.push(esc(d.summary)); lines.push(''); }
  lines.push(links.join(' · '));
  return lines.join('\n');
}

function renderBlock(docs) {
  const body = docs.length === 0
    ? 'None yet.'
    : docs.map(renderEntry).join('\n\n');
  return [BEGIN_MARKER, '', '## Delivered features (generated)', '', body, '', END_MARKER].join('\n');
}

// Splice `block` into `content` at the marked region (containment): replace
// an existing BEGIN..END span in place, or append the block at EOF (with a
// single blank-line separator) when no markers exist yet (first run).
function spliceMarkedRegion(content, block) {
  const beginMatch = BEGIN_RE.exec(content);
  if (!beginMatch) {
    const trimmed = content.replace(/\n+$/, '');
    const sep = trimmed.length === 0 ? '' : '\n\n';
    return `${trimmed}${sep}${block}\n`;
  }
  const beginIdx = beginMatch.index;
  END_RE.lastIndex = 0;
  const tail = content.slice(beginIdx);
  const endMatch = END_RE.exec(tail);
  if (!endMatch) {
    throw new Error('found a BEGIN marker with no matching END marker — refusing to guess a splice point');
  }
  const before = content.slice(0, beginIdx);
  const after = tail.slice(endMatch.index + endMatch[0].length);
  return `${before}${block}${after}`;
}

function main() {
  const args = parseArgs(process.argv);
  const docs = loadProductDocs(ROOT);
  const block = renderBlock(docs);
  const outPath = path.resolve(ROOT, args.outputPath);
  let existing = '';
  try { existing = fs.readFileSync(outPath, 'utf8'); } catch { /* first run: no file yet */ }
  const next = spliceMarkedRegion(existing, block);
  fs.writeFileSync(outPath, next);
  console.log(`userguide-rollup: ${docs.length} delivered feature(s) rendered -> ${path.relative(ROOT, outPath)}`);
}

main();
